<template>
 <section aria-label="本地病例统计独立审计">
  <p>技术目录、真实用量和不透明SHA不授予正文权限。即使超级管理员，读取任何完整来源、任务或结果仍须当前逐患者感染监测处理许可；没有冻结正文旁路。</p>
  <template v-if="allowed"><el-button v-if="directoryEnabled" :loading="busy" @click="refresh">读取病例统计技术任务目录</el-button><el-button v-if="initialMetadata" :disabled="busy" @click="inspect(initialMetadata)">重新核对所选任务技术溯源</el-button><el-button @click="clear()">关闭本地统计审计并清除拆分件</el-button><p v-if="error" role="alert">{{error}}</p>
   <el-table v-if="directory" :data="directory.items" row-key="run_id" aria-label="完整病例统计技术审计目录"><el-table-column prop="run_id" label="真实任务UUID"/><el-table-column prop="scenario_id" label="原完整比较族UUID"/><el-table-column prop="status" label="当前状态"/><el-table-column prop="usage_receipt_status" label="真实收据状态"/><el-table-column label="明确读取"><template #default="{row}"><el-button @click="inspect(row)">核对本条技术溯源</el-button></template></el-table-column></el-table><el-pagination v-if="directory?.total>20" v-model:current-page="page" :page-size="20" :total="directory.total" layout="prev,pager,next,total" @current-change="refresh"/>
   <div v-if="metadata" aria-label="已核验本地审计技术状态"><p>{{metadata.run_id}} · {{metadata.status}}；外部模型tokens为0。CPU尝试{{tri(metadata.usage?.calculation_attempted)}}，完成{{tri(metadata.usage?.calculation_completed)}}；{{metadata.usage_receipt_status==='recorded'?'真实用量审计PK '+metadata.receipt_event_id:'实际CPU回执尚待记录，不视为零'}}。</p><p>来源SHA{{metadata.source_hash}}是服务端不透明锚；本条尚未因此获得临床来源读取资格。</p><el-button :disabled="busy" @click="inspect(metadata,{clinical:true})">以当前逐患者许可读取全部拆分件</el-button></div>
   <InfectionFindings v-if="detail" :value="detail" :active="active&&allowed" @invalidate="clearParts" @closed="clearParts"/>
  </template><p v-else>当前身份不能读取超级管理员审计，旧拆分件已清除。</p>
 </section>
</template>
<script setup>
import{computed,onBeforeUnmount,onDeactivated,ref,watch}from'vue';import{useStore}from'vuex';import InfectionFindings from'./InfectionFindings.vue';import{canonical,same}from'@/api/ai/infectionClusterProofs';import{getInfectionTask,getInfectionTasks,getInfectionTaskTrace,infectionTaskDirectoryValid,readInfectionTaskParts,verifyInfectionSplitTrace,verifyInfectionTaskMetadata}from'@/api/ai/infectionClusterTasks';
const props=defineProps({active:{type:Boolean,default:true},initialMetadata:{default:null},directoryEnabled:{type:Boolean,default:true}}),store=useStore(),directory=ref(null),metadata=ref(null),detail=ref(null),busy=ref(false),error=ref(''),page=ref(1);let epoch=0;
const identity=computed(()=>canonical({active:props.active,initial:props.initialMetadata,token:store.state.user?.accessToken??null,name:store.state.user?.username??null,roles:store.getters['user/permissions']??store.state.user?.permissions??[]})),allowed=computed(()=>props.active&&!!store.state.user?.accessToken&&(store.getters['user/permissions']??store.state.user?.permissions??[]).includes('super_admin'));
function clear({all=false}={}){++epoch;metadata.value=null;detail.value=null;busy.value=false;error.value='';if(all){directory.value=null;page.value=1;}}
const tri=v=>v===true?'是':v===false?'否':'未知',clearParts=()=>detail.value=null;
async function operation(fn){if(!allowed.value)return;const t=++epoch,key=identity.value,current=()=>t===epoch&&key===identity.value&&allowed.value;detail.value=null;metadata.value=null;error.value='';busy.value=true;try{await fn(current);}catch{if(current()){detail.value=null;error.value='当前完整审计或逐患者目的许可无法核对；未恢复任务、来源或结果正文。';}}finally{if(current())busy.value=false;}}
async function refresh(){if(!props.directoryEnabled)return;directory.value=null;return operation(async current=>{const v=(await getInfectionTasks({page:page.value,size:20})).data;if(!infectionTaskDirectoryValid(v,{page:page.value,size:20})||!current())throw Error();directory.value=JSON.parse(canonical(v));});}
async function inspect(row,{clinical=false}={}){if(!verifyInfectionTaskMetadata(row))return;const rowText=canonical(row),listed=directory.value?.items.some(v=>canonical(v)===rowText)||props.initialMetadata&&canonical(props.initialMetadata)===rowText||metadata.value&&canonical(metadata.value)===rowText;if(!listed)return;return operation(async current=>{const v=(await getInfectionTask(row.run_id)).data;if(!verifyInfectionTaskMetadata(v,{runId:row.run_id,scenarioId:row.scenario_id,current})||!['snapshot_id','profile_id','created_at','source_hash','source_bytes','preview'].every(k=>same(v[k],row[k])))throw Error();if(!current())return;metadata.value=JSON.parse(canonical(v));const trace=(await getInfectionTaskTrace(row.run_id)).data;if(!verifyInfectionSplitTrace(trace,{runId:row.run_id,metadata:v,current}))throw Error();if(clinical){const parts=await readInfectionTaskParts(row.run_id,{current});if(!current()||!same(parts.metadata,trace.run))throw Error();detail.value=parts;}});}
watch(identity,()=>clear({all:true}),{immediate:true,flush:'sync'});onDeactivated(()=>clear({all:true}));onBeforeUnmount(()=>clear({all:true}));
</script>
<style scoped>p{line-height:1.7;overflow-wrap:anywhere}.el-button{margin:5px}</style>
